"""Security and AST integrity audits for skills and framework."""

from __future__ import annotations

import ast
import os
from pathlib import Path
from typing import List, Tuple

import pytest

from skillware.core.base_skill import BaseSkill

REPO_ROOT = Path(__file__).resolve().parent.parent
SKILLS_ROOT = REPO_ROOT / "skills"
SKILLWARE_ROOT = REPO_ROOT / "skillware"

FORBIDDEN_CALLS = frozenset({"eval", "exec", "compile", "__import__"})


def _discover_python_files(root_dir: Path, exclude_tests: bool = True) -> List[Path]:
    py_files: List[Path] = []
    if not root_dir.is_dir():
        return py_files
    for p in root_dir.rglob("*.py"):
        if exclude_tests and p.name.startswith("test_"):
            continue
        py_files.append(p)
    return sorted(py_files)


def test_no_dynamic_code_execution_primitives_in_skills():
    """Verify that no skill contains eval(), exec(), compile(), or __import__()."""
    files = _discover_python_files(SKILLS_ROOT, exclude_tests=False)
    assert files, "expected at least one Python file under skills/"

    violations: List[Tuple[str, str, int]] = []
    for file_path in files:
        content = file_path.read_text(encoding="utf-8")
        try:
            tree = ast.parse(content, filename=str(file_path))
        except SyntaxError as exc:
            pytest.fail(f"Syntax error in {file_path}: {exc}")

        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                if node.func.id in FORBIDDEN_CALLS:
                    rel_path = file_path.relative_to(REPO_ROOT).as_posix()
                    violations.append((rel_path, node.func.id, node.lineno))

    assert (
        not violations
    ), "Forbidden dynamic execution calls found in skills:\n" + "\n".join(
        f"  {path}:{line} calls {fn}()" for path, fn, line in violations
    )


def test_no_direct_credential_reads_from_os_environ():
    """
    Ensure skills do not bypass BaseSkill.credential() by reading API keys directly
    from os.environ.
    """
    files = _discover_python_files(SKILLS_ROOT, exclude_tests=True)
    violations: List[Tuple[str, str, int]] = []

    # Whitelisted non-credential environment variables (e.g. scratch directory paths)
    allowed_env_vars = frozenset({"SKILLWARE_SCRATCH_DIR"})

    for file_path in files:
        content = file_path.read_text(encoding="utf-8")
        try:
            tree = ast.parse(content, filename=str(file_path))
        except SyntaxError as exc:
            pytest.fail(f"Syntax error in {file_path}: {exc}")

        for node in ast.walk(tree):
            # Check os.environ.get("...") calls
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "get"
                and isinstance(node.func.value, ast.Attribute)
                and node.func.value.attr == "environ"
                and isinstance(node.func.value.value, ast.Name)
                and node.func.value.value.id == "os"
            ):
                if node.args and isinstance(node.args[0], ast.Constant):
                    var_name = str(node.args[0].value)
                    if var_name not in allowed_env_vars:
                        rel_path = file_path.relative_to(REPO_ROOT).as_posix()
                        violations.append((rel_path, var_name, node.lineno))

            # Check os.environ["..."] subscript reads
            if (
                isinstance(node, ast.Subscript)
                and isinstance(node.value, ast.Attribute)
                and node.value.attr == "environ"
                and isinstance(node.value.value, ast.Name)
                and node.value.value.id == "os"
            ):
                if isinstance(node.slice, ast.Constant):
                    var_name = str(node.slice.value)
                    if var_name not in allowed_env_vars:
                        rel_path = file_path.relative_to(REPO_ROOT).as_posix()
                        violations.append((rel_path, var_name, node.lineno))

    assert not violations, (
        "Direct os.environ credential reads found in skill code. Use self.credential() instead:\n"
        + "\n".join(
            f"  {path}:{line} reads os.environ['{var}']"
            for path, var, line in violations
        )
    )


def test_credential_fn_sandboxing_isolation(monkeypatch):
    """Verify that BaseSkill credential_fn provides complete sandboxed resolution."""
    monkeypatch.delenv("PRIVATE_SECRET", raising=False)

    resolved_keys: List[str] = []

    def mock_key_vault(key: str) -> str | None:
        resolved_keys.append(key)
        if key == "PRIVATE_SECRET":
            return "super-secret-vault-token"
        return None

    class _MockSkill(BaseSkill):
        @property
        def manifest(self):
            return {"name": "test/mock_skill"}

        def execute(self, params):
            return {"token": self.credential("PRIVATE_SECRET")}

    skill = _MockSkill(credential_fn=mock_key_vault)
    result = skill.execute({})

    assert result["token"] == "super-secret-vault-token"
    assert resolved_keys == ["PRIVATE_SECRET"]
    # Ensure os.environ was never populated or accessed
    assert "PRIVATE_SECRET" not in os.environ

"""Tests for pluggable secret providers."""

from __future__ import annotations

from skillware import SkillContext
from skillware.core.loader import SkillLoader
from skillware.core.secrets import (
    CallableSecretProvider,
    EnvSecretProvider,
    MappingSecretProvider,
    audit_manifest_env_vars,
    resolve_manifest_env_vars,
)

MANIFEST_WITH_ENV = {
    "env_vars": {
        "ETHERSCAN_API_KEY": {"description": "Required", "required": True},
        "COINGECKO_API_KEY": {"description": "Optional", "required": False},
    }
}


def test_mapping_secret_provider_returns_injected_values():
    provider = MappingSecretProvider({"ETHERSCAN_API_KEY": "vault-key"})
    assert provider.get("ETHERSCAN_API_KEY") == "vault-key"
    assert provider.get("COINGECKO_API_KEY") is None


def test_env_secret_provider_reads_os_environ(monkeypatch):
    monkeypatch.setenv("ETHERSCAN_API_KEY", "from-env")
    provider = EnvSecretProvider()
    assert provider.get("ETHERSCAN_API_KEY") == "from-env"


def test_env_secret_provider_treats_blank_as_missing(monkeypatch):
    monkeypatch.setenv("ETHERSCAN_API_KEY", "   ")
    provider = EnvSecretProvider()
    assert provider.get("ETHERSCAN_API_KEY") is None


def test_resolve_manifest_env_vars_uses_provider():
    provider = MappingSecretProvider(
        {"ETHERSCAN_API_KEY": "injected", "COINGECKO_API_KEY": ""}
    )
    resolved = resolve_manifest_env_vars(MANIFEST_WITH_ENV, provider)
    assert resolved == {"ETHERSCAN_API_KEY": "injected"}


def test_skill_loader_resolve_env_vars_defaults_to_env(monkeypatch):
    monkeypatch.setenv("ETHERSCAN_API_KEY", "loader-env")
    resolved = SkillLoader.resolve_env_vars(MANIFEST_WITH_ENV)
    assert resolved["ETHERSCAN_API_KEY"] == "loader-env"


def test_skill_loader_resolve_env_vars_empty_manifest():
    assert SkillLoader.resolve_env_vars({}) == {}
    assert SkillLoader.resolve_env_vars({"env_vars": "invalid"}) == {}


def test_callable_secret_provider():
    calls: list[str] = []

    def fetch(key: str) -> str | None:
        calls.append(key)
        return f"value-for-{key}"

    provider = CallableSecretProvider(fetch)
    assert provider.get("ETHERSCAN_API_KEY") == "value-for-ETHERSCAN_API_KEY"
    assert calls == ["ETHERSCAN_API_KEY"]


def test_audit_manifest_env_vars_missing_required():
    status, detail = audit_manifest_env_vars(
        MANIFEST_WITH_ENV,
        MappingSecretProvider({}),
    )
    assert status == "fail"
    assert "ETHERSCAN_API_KEY" in detail


def test_audit_manifest_env_vars_ok_when_present():
    status, detail = audit_manifest_env_vars(
        MANIFEST_WITH_ENV,
        MappingSecretProvider({"ETHERSCAN_API_KEY": "present"}),
    )
    assert status == "ok"
    assert detail == ""


def test_audit_manifest_env_vars_skip_when_undeclared():
    status, detail = audit_manifest_env_vars({"name": "test/skill"})
    assert status == "—"
    assert detail == ""


class _EphemeralTokenProvider:
    def __init__(self) -> None:
        self.calls = 0

    def get(self, key: str) -> str | None:
        if key != "ETHERSCAN_API_KEY":
            return None
        self.calls += 1
        return f"token-{self.calls}"


def test_skill_context_re_resolves_secrets_each_execute(monkeypatch):
    monkeypatch.delenv("ETHERSCAN_API_KEY", raising=False)
    provider = _EphemeralTokenProvider()
    ctx = SkillContext(skill="finance/wallet_screening", secret_provider=provider)
    prep = ctx.prepare("finance/wallet_screening")
    skill_cls = SkillLoader.get_skill_class(dict(prep.bundle))
    captured: list[str | None] = []

    def fake_execute(self, params):
        captured.append(self.etherscan_api_key)
        return {"status": "mocked"}

    monkeypatch.setattr(skill_cls, "execute", fake_execute)
    address = {"address": "0x0000000000000000000000000000000000000001"}
    ctx.execute("finance/wallet_screening", address)
    ctx.execute("finance/wallet_screening", address)
    assert captured == ["token-1", "token-2"]
    assert provider.calls == 2


def test_skill_context_accepts_secret_mapping(monkeypatch):
    monkeypatch.delenv("ETHERSCAN_API_KEY", raising=False)
    ctx = SkillContext(
        skill="finance/wallet_screening",
        secret_provider={"ETHERSCAN_API_KEY": "host-injected"},
    )
    prep = ctx.prepare("finance/wallet_screening")
    skill_cls = SkillLoader.get_skill_class(dict(prep.bundle))
    captured: list[str | None] = []

    def fake_execute(self, params):
        captured.append(self.etherscan_api_key)
        return {"status": "mocked"}

    monkeypatch.setattr(skill_cls, "execute", fake_execute)
    ctx.execute(
        "finance/wallet_screening",
        {"address": "0x0000000000000000000000000000000000000001"},
    )
    assert captured == ["host-injected"]

